  "exp": "대통령 외의 공무원(국무위원 등)에 대한 탄핵소추는 재적의원 3분의 1 이상의 발의와 재적의원 과반수의 찬성으로 의결한다(헌법 제65조 제2항). 대통령은 재적 과반수 발의·재적 3분의 2 이상 찬성이다. 해임건의는 제63조, 권한행사 정지는 제65조 제3항.",
