  "q": "甲은 스스로 술을 과하게 마셔 심신상실 상태에 이른 뒤 행인 乙을 밀쳐 다치게 하였다. 민법상 甲과 관련자의 책임에 관한 설명으로 옳은 것은? (다툼이 있는 경우 판례에 의함)",
  "opts": [
   "가해행위 당시 甲이 심신상실 상태였던 이상 그 상태에 이르게 된 경위와 관계없이 甲은 손해배상책임을 지지 않는다.",
   "甲이 심신상실을 이유로 책임을 면하는 경우 그를 감독할 법정의무가 있는 자는 감독의무를 게을리하지 않았음을 증명하더라도 배상책임을 면하지 못한다.",
   "감독의무자를 갈음하여 책임무능력자를 감독하는 자는 법정 감독의무자가 아니므로 민법 제755조의 책임을 지지 않는다.",
   "甲이 고의 또는 과실로 심신상실을 초래한 것이라면 심신상실 중의 가해행위라도 甲은 손해배상책임을 진다."
  ],
  "ans": 3,
  "exp": "심신상실 중에 타인에게 손해를 가한 자는 배상책임이 없으나, 고의 또는 과실로 심신상실을 초래한 때에는 그러하지 아니하다(민법 제754조). 스스로 과음하여 심신상실에 이른 甲은 원인에 있어 과실이 있으므로 책임을 진다. 책임무능력자의 감독의무자는 감독의무를 게을리하지 않았음을 증명하면 면책되고(제755조 제1항 단서), 감독의무자를 갈음하여 감독하는 자도 같은 책임을 진다(같은 조 제2항).",
  "ref": "민법 제754조, 제755조",
  "why": [
   "× 고의·과실로 심신상실을 초래한 때에는 책임을 면하지 못한다(제754조 단서).",
   "× 감독의무를 게을리하지 않았으면 면책된다(제755조 제1항 단서).",
   "× 대리감독자도 제755조 제1항의 책임을 진다(제755조 제2항).",
   "○ 제754조 단서 — 원인에 있어 자유로운 행위."
  ],
