  "q": "교통사고 피해자가 국민연금 장애연금을 받은 후 가해자에게 손해배상을 청구한 경우에 관한 대법원 전원합의체 판결(2024. 6. 20. 선고 2021다299594)의 태도로 옳은 것은? (피해자에게도 과실이 있음)",
  "opts": [
   "국민연금공단은 지급한 장애연금 전액의 범위에서 피해자의 가해자에 대한 손해배상청구권을 대위한다.",
   "장애연금 중 피해자 과실비율에 해당하는 부분은 공단이 가해자에게 구상하여 회수할 수 있다.",
   "손해액에서 장애연금을 먼저 공제한 뒤 과실상계를 하는 방식으로 배상액을 산정한다.",
   "이 판결은 국민연금에 한정되므로 건강보험·산재보험 급여는 종전처럼 과실상계를 먼저 한 뒤 공제한다."
  ],
  "ans": 2,
  "exp": "전원합의체는 연금급여를 받은 피해자의 손해배상액은 손해액에서 연금급여액을 먼저 공제한 뒤 과실상계하여야 하고, 공단이 대위하는 범위는 연금급여액 전액이 아니라 그중 가해자의 책임비율에 해당하는 금액으로 제한된다고 하였다. 피해자 과실비율 부분은 피해자가 누리고 공단이 최종 부담한다. 건강보험(2018다287935)·산재보험(2021다241618)도 이미 전원합의체로 같은 취지로 변경되었다.",
  "ref": "대법원 2024. 6. 20. 선고 2021다299594 전원합의체 판결, 국민연금법 제114조 제1항, 민법 제763조·제396조",
