  "q": "보험약관의 해석에 관한 설명으로 옳은 것은? (다툼이 있는 경우 판례에 의함)",
  "opts": [
   "약관의 뜻이 명백하지 않은 경우에는 약관을 작성한 보험자의 의도를 우선하여 해석하여야 한다.",
   "약관에 수술의 정의가 없다면, 혈관에 가는 관을 넣어 약물을 주입하는 색전술도 '수술'에 해당할 수 있다.",
   "약관은 개별 보험계약자의 학력·경험 등 구체적 이해능력을 기준으로 계약자마다 달리 해석하여야 한다.",
   "'암의 치료를 직접 목적으로 하는 수술'에는 암 치료 후 생긴 후유증 완화나 합병증 치료를 위한 수술까지 포함된다고 보아야 한다."
  ],
  "ans": 1,
  "exp": "약관은 고객에 따라 다르게 해석되어서는 아니 되고, 뜻이 명백하지 않으면 고객에게 유리하게 해석한다(약관규제법 제5조). 대법원 2010. 7. 22. 선고 2010다28208 판결은 색전술도 넓은 의미의 수술에 포함될 여지가 충분하다며 약관상 '수술'에 해당한다고 보았다. 반면 대법원 2010. 9. 30. 선고 2010다40543 판결은 암 치료 후 후유증 완화나 합병증 치료를 위한 수술까지 '암의 직접 치료 목적 수술'에 포함된다고 보기 어렵다고 하였다.",
  "ref": "약관의 규제에 관한 법률 제5조, 대법원 2010. 7. 22. 선고 2010다28208 판결, 대법원 2010. 9. 30. 선고 2010다40543 판결",
  "why": [
   "× 뜻이 명백하지 않으면 고객에게 유리하게 해석한다(약관규제법 제5조 제2항).",
   "○ 2010다28208 — 색전술도 약관상 수술.",
   "× 고객에 따라 다르게 해석되어서는 아니 된다(약관규제법 제5조 제1항).",
   "× 2010다40543 — 합병증 치료 수술까지 포함된다고 보기 어렵다."
  ],
  "rel": "2026-11-13",
