 "rel": "2026-11-23",
 "case": "갑은 고의로 을을 살해하였고, 갑의 사용자 병은 사용자책임을 진다. 을의 유족은 국가로부터 범죄피해구조금(유족구조금)을 받았다. 손해배상 소송에서 피해자 측 과실을 이유로 한 책임 제한이 병에게만 적용되어, 갑이 배상할 금액이 병보다 많게 산정되었다.",
 "q": "다음 사례에서 범죄피해구조금의 공제에 관한 설명으로 옳지 않은 것은? (다툼이 있는 경우 판례에 의함)",
