 "exp": "대법원 2002. 6. 28. 선고 2002다22106 판결: 방어비용은 원칙적으로 보험사고 발생을 전제로 하나, 사고 당시 피보험자의 법률상 책임 여부가 판명되지 않은 상태에서 피해자의 청구를 방어하기 위해 지출한 재판상·재판 외 필요비용은 보험자가 부담하고(사안은 피보험자가 손해배상소송에서 승소), 지출이 명백히 예상되면 선급도 청구할 수 있다. 보험자의 사전 동의가 없으면 방어비용을 인정하지 않는다고 해석되는 약관조항은 제720조 제1항을 피보험자에게 불리하게 변경한 것으로 제663조에 반하여 무효다(설명 여부와 무관). 대법원 94다27076 판결: 방어비용은 피해자가 피보험자를 상대로 손해배상청구를 한 경우 그 방어를 위한 비용이므로, 피해자가 피보험자에게 재판상·재판 외 청구를 전혀 하지 않았다면 제3자를 상대로 한 소송의 변호사 비용은 방어비용이 아니다.",
